sys_script.script:
// Now Assist Cost Lens — Capture VA Conversation on close
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function executeRule(current, previous /*null when async*/) {
    try {
        var tracker = new NACLCostTracker();
        tracker.captureInteraction(current.getUniqueValue());
    } catch (e) {
        gs.error('NACL BR: Failed to capture VA conversation ' + current.getUniqueValue() + ': ' + e.message);
    }
})(current, previous);
